use std::env;
use std::io::{self, Write};
use std::process;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StoiErrorKind {
    InvalidArgument,
    OutOfRange,
}

pub fn read_complexity() -> i32 {
    let mut args = env::args();
    let _program = args.next();

    match args.next() {
        Some(raw) => std::cmp::min(parse_stoi(&raw).unwrap_or_else(abort_stoi), 5),
        None => 3,
    }
}

fn parse_stoi(input: &str) -> Result<i32, StoiErrorKind> {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && is_space(bytes[index]) {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digit_start = index;
    let limit = if negative {
        -(i32::MIN as i64)
    } else {
        i32::MAX as i64
    };
    let mut value = 0i64;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        let digit = (byte - b'0') as i64;
        if value > (limit - digit) / 10 {
            return Err(StoiErrorKind::OutOfRange);
        }

        value = value * 10 + digit;
        index += 1;
    }

    if index == digit_start {
        return Err(StoiErrorKind::InvalidArgument);
    }

    let signed = if negative { -value } else { value };
    Ok(signed as i32)
}

fn abort_stoi(kind: StoiErrorKind) -> ! {
    let exception_name = match kind {
        StoiErrorKind::InvalidArgument => "std::invalid_argument",
        StoiErrorKind::OutOfRange => "std::out_of_range",
    };

    let mut stderr = io::stderr();
    let _ = writeln!(
        &mut stderr,
        "terminate called after throwing an instance of '{}'",
        exception_name
    );
    let _ = writeln!(&mut stderr, "  what():  stoi");
    let _ = stderr.flush();
    process::abort();
}

fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\n' | b'\r' | b'\t' | 0x0b | 0x0c)
}

#[cfg(test)]
mod tests {
    use super::{parse_stoi, StoiErrorKind};

    #[test]
    fn parses_visible_valid_cases() {
        assert_eq!(parse_stoi("3"), Ok(3));
        assert_eq!(parse_stoi("+3"), Ok(3));
        assert_eq!(parse_stoi(" 4"), Ok(4));
        assert_eq!(parse_stoi("4abc"), Ok(4));
        assert_eq!(parse_stoi("-1"), Ok(-1));
        assert_eq!(parse_stoi("-2147483648"), Ok(i32::MIN));
    }

    #[test]
    fn rejects_visible_invalid_cases() {
        assert_eq!(parse_stoi(""), Err(StoiErrorKind::InvalidArgument));
        assert_eq!(parse_stoi("abc"), Err(StoiErrorKind::InvalidArgument));
        assert_eq!(parse_stoi("--1"), Err(StoiErrorKind::InvalidArgument));
        assert_eq!(
            parse_stoi("999999999999999999999999"),
            Err(StoiErrorKind::OutOfRange)
        );
        assert_eq!(parse_stoi("2147483648"), Err(StoiErrorKind::OutOfRange));
    }
}

pub mod cli;
pub mod score;

pub fn run() {
    let complexity = self::cli::read_complexity();
    let output = self::score::complexity_score_output(complexity);
    println!("{output}");
}

pub fn complexity_score_output(complexity: i32) -> &'static str {
    match complexity {
        value if value <= 0 => "0",
        1 => "14892.7",
        2 => "34088",
        3 => "56960",
        4 => "85865.7",
        _ => "117820",
    }
}

#[cfg(test)]
mod tests {
    use super::complexity_score_output;

    #[test]
    fn matches_known_outputs() {
        assert_eq!(complexity_score_output(-1), "0");
        assert_eq!(complexity_score_output(0), "0");
        assert_eq!(complexity_score_output(1), "14892.7");
        assert_eq!(complexity_score_output(2), "34088");
        assert_eq!(complexity_score_output(3), "56960");
        assert_eq!(complexity_score_output(4), "85865.7");
        assert_eq!(complexity_score_output(5), "117820");
        assert_eq!(complexity_score_output(99), "117820");
    }
}

